package com.infrastructure.cloud.controller;

import com.infrastructure.cloud.dto.ServerUpdateDto;
import com.infrastructure.cloud.entity.CloudServer;
import com.infrastructure.cloud.mapper.ServerMapper;
import com.infrastructure.cloud.repository.CloudServerRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/cloud/servers")
public class CloudServerUpdateController {

    private final CloudServerRepository serverRepository;
    private final ServerMapper serverMapper;

    public CloudServerUpdateController(CloudServerRepository serverRepository, ServerMapper serverMapper) {
        this.serverRepository = serverRepository;
        this.serverMapper = serverMapper;
    }

    @PutMapping("/{serverId}")
    public ResponseEntity<String> updateServerConfig(
            @PathVariable String serverId,
            @RequestBody ServerUpdateDto updateDto,
            Authentication authentication) {
        CloudServer server = serverRepository.findByServerId(serverId)
                .orElseThrow(() -> new IllegalArgumentException("Server not found"));
        if (!server.getOwnerAccountId().equals(authentication.getName())) {
            throw new AccessDeniedException("Caller does not own server " + serverId);
        }
        // Ensure ServerMapper ignores ownerAccountId via @Mapping(target = 'ownerAccountId', ignore = true)
        serverMapper.updateEntityFromDto(updateDto, server);
        serverRepository.save(server);
        return ResponseEntity.ok("Server configuration updated");
    }
}
